import type { Metadata } from "next";
import { notFound } from "next/navigation";
import ProjectDetail from "@/components/sections/ProjectDetail";
import { getProject, projects } from "@/content/projects";

/**
 * French case-study route. The English tree lives at /en/projects/[slug] and is
 * generated by its own page — the two exist so each language gets a URL in its
 * own words rather than one shared spelling.
 */
export function generateStaticParams() {
  return projects.map((project) => ({ lang: "fr", slug: project.slug }));
}

export const dynamicParams = false;

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const project = getProject(slug);
  if (!project) return {};

  const copy = project.copy.fr;
  return {
    title: `${copy.title} — Christian Bakiti Kamga`,
    description: copy.tagline,
    openGraph: { title: copy.title, description: copy.tagline, locale: "fr_FR" },
  };
}

export default async function FrenchProjectPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const project = getProject(slug);
  if (!project) notFound();

  return <ProjectDetail project={project} lang="fr" />;
}
